/** Play the same completion chime as dsh-notify-sound, using its saved prefs. */
export async function playNotifySound(): Promise<void> {
  try {
    const response = await fetch('/notify-sound/api/prefs.get', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: '{}',
    })
    const body: unknown = await response.json()
    const envelope = body !== null && typeof body === 'object' ? body as { ok?: unknown; value?: unknown } : undefined
    const view = envelope?.ok === true ? envelope.value : undefined
    const prefs = view !== null && typeof view === 'object' ? (view as { value?: unknown }).value : undefined
    const value = prefs !== null && typeof prefs === 'object' ? prefs as { enabled?: unknown; sound?: unknown; volume?: unknown } : undefined
    if (value?.enabled === false) return
    const sound = typeof value?.sound === 'string' && value.sound !== '' ? value.sound : 'staplebops-01.aac'
    const volume = typeof value?.volume === 'number' && Number.isFinite(value.volume) ? Math.min(1, Math.max(0, value.volume)) : 0.8
    const audio = new Audio(`/notify-sound/sounds/${sound}`)
    audio.volume = volume
    await audio.play().catch(() => { /* autoplay may be blocked until a click */ })
  } catch {
    // The notify-sound plugin is optional.
  }
}
