/**
 * Image-gen panel controller: the single owner of the panel's open/closed
 * state and of background generation status. Framework-free so the DOM
 * mounts and the React panel share one tiny subscription surface.
 */

/** Sidebar / header job indicator. */
export type ImageGenJobState = 'idle' | 'generating' | 'ready' | 'error'

/** Immutable controller snapshot for UI subscriptions. */
export interface ImageGenControllerSnapshot {
  panelOpen: boolean
  jobState: ImageGenJobState
}

/** The panel state owner the sidebar entry toggles and the view renders from. */
export class ImageGenController {
  private panelOpen = false
  private jobState: ImageGenJobState = 'idle'
  private listeners = new Set<() => void>()

  getSnapshot(): ImageGenControllerSnapshot {
    return { panelOpen: this.panelOpen, jobState: this.jobState }
  }

  subscribe(fn: () => void): () => void {
    this.listeners.add(fn)
    return () => { this.listeners.delete(fn) }
  }

  open(): void {
    const clearReady = this.jobState === 'ready' || this.jobState === 'error'
    if (this.panelOpen && !clearReady) return
    this.panelOpen = true
    if (clearReady) this.jobState = 'idle'
    this.notify()
  }

  close(): void {
    if (!this.panelOpen) return
    this.panelOpen = false
    this.notify()
  }

  toggle(): void {
    if (this.panelOpen) this.close()
    else this.open()
  }

  startJob(): void {
    if (this.jobState === 'generating') return
    this.jobState = 'generating'
    this.notify()
  }

  finishJob(ok: boolean): void {
    this.jobState = ok ? 'ready' : 'error'
    this.notify()
  }

  private notify(): void {
    for (const fn of [...this.listeners]) fn()
  }
}
